import java.io.BufferedReader;import java.io.InputStreamReader;import java.io.PrintWriter;import java.util.StringTokenizer;public class TestClass {public static void main(String[] args) throws Exception {BufferedReader br = new BufferedReader(new InputStreamReader(System.in));PrintWriter out = new PrintWriter(System.out);String line = br.readLine();if (line != null) {int n = Integer.parseInt(line.trim());for (int i = 0; i < n; i++) {String input = br.readLine();if (input != null) {out.println(input);}}}out.flush();out.close();}}